function initPkg_BagInfo_Func() {
    let backpackDom = getValidDom([ ".BackpackButton", "#js-backpack-enter" ]);
    if (!backpackDom) return;
    backpackDom.addEventListener("click", function() {
        setTimeout(() => {
            if (bagInfoDomHook) bagInfoDomHook.closeHook(), bagInfoDomHook = null;
            let giftItemNum = document.querySelectorAll(".ToolbarBackpack-giftItem").length;
            bagInfoDomHook = new DomHook(".BackpackExpandPanel-giftListWrap", true, e => {
                if (giftItemNum != document.querySelectorAll(".ToolbarBackpack-giftItem").length) backpackDom.click(), 
                backpackDom.click();
            });
        }, 500), clearTimeout(timeout), timeout = setTimeout(() => {
            const isBeta = !!document.getElementsByClassName("BackpackExpandPanel")[0];
            if (getValidDom([ ".Backpack.JS_Backpack", ".BackpackExpandPanel" ])) getBagGifts(rid, ret => {
                if (!ret || !ret.data || !Array.isArray(ret.data.list)) return;
                let chunkNum = ret.data.list.length;
                if (chunkNum > 0) {
                    let totalPrice = 0;
                    let totalIntimate = 0;
                    let chunkList = getValidDomList([ ".Backpack-prop", ".ToolbarBackpack-giftItem" ]);
                    for (let i = 0; i < chunkNum; i++) {
                        let chunk = chunkList[i];
                        let isValuable = ret.data.list[i].isValuable;
                        let expiry = ret.data.list[i].expiry;
                        let price = ret.data.list[i].price;
                        let intimate = ret.data.list[i].intimate;
                        let count = ret.data.list[i].count;
                        if ("1" == isValuable) totalPrice += Number(price) * Number(count);
                        totalIntimate += Number(intimate) * Number(count);
                        let expiryText = BagInfo_formatExpiry(expiry);
                        if (!chunk || !expiryText) continue;
                        let expiryDiv = document.createElement("div");
                        if (expiryDiv.className = "bag-info", isBeta) expiryDiv.style.left = "2px", 
                        expiryDiv.style.bottom = "2px";
                        expiryDiv.textContent = expiryText, chunk.insertBefore(expiryDiv, chunk.childNodes[0]);
                    }
                    const headerDom = getValidDom([ ".BackpackHeader-extInfo", ".BackpackExpandPanel-backpackHeader" ]);
                    if (!headerDom) return;
                    if (isBeta) headerDom.innerHTML = headerDom.innerHTML + `<span class="dx-w-100 dx-d-flex dx-jc-space-between dx-ai-center dx-flex-1 dx-ml-12" >
                                <span>
                                    <span>总价值:</span>
                                    <span>￥${String(Number(totalPrice / 100).toFixed(2))}</span>
                                    <span>总亲密度:</span>
                                    <span>${String(totalIntimate)}</span>
                                </span>
                                <span class="bag-button dx-ink-white!important dx-bg-rgb70171255" id="Backpack__clearbag" >清空背包</span>
                            </span>`; else headerDom.innerHTML = `<span class="dx-float-left" >` + "总价值：" + String(Number(totalPrice / 100).toFixed(2)) + " 总亲密度：" + String(totalIntimate) + `<span class="bag-button" id="Backpack__clearbag">清空背包</span></span>` + headerDom.innerHTML;
                    let clearBtn = document.getElementById("Backpack__clearbag");
                    if (clearBtn) clearBtn.addEventListener("click", () => {
                        if (true != confirm("确认清空？")) return;
                        showMessage("【清空背包】执行中...", "info"), getBagGifts(rid, ret => {
                            clearBagGifts(ret, rid);
                        });
                    });
                }
            });
        }, 500);
    });
}

function BagInfo_formatExpiry(expiry) {
    if (null === expiry || "undefined" === typeof expiry || "" === expiry) return "";
    let n = Number(expiry);
    if (!isFinite(n) || n < 0) return "";
    if (n >= 1e9) {
        let ms = n < 1e12 ? 1e3 * n : n;
        let d = new Date(ms);
        if (isNaN(d.getTime())) return "";
        if ("function" === typeof dateFormat) return dateFormat("yyyy-MM-dd", d);
        return d.getFullYear() + "-" + ("0" + (d.getMonth() + 1)).slice(-2) + "-" + ("0" + d.getDate()).slice(-2);
    }
    let days = Math.floor(n);
    return days <= 0 ? "今天到期" : "剩 " + days + " 天";
}

async function clearBagGifts(bagGiftsJson, room_id) {
    let chunkNum = bagGiftsJson.data.list.length;
    if (chunkNum > 0) {
        for (let i = 0; i < chunkNum; i++) {
            let gift_id = bagGiftsJson.data.list[i].id;
            let gift_cnt = bagGiftsJson.data.list[i].count;
            if (Object.keys(bagGiftsJson.data.list[i].batchInfo).length > 0) await sleep(100).then(() => {
                sendGift_bag(gift_id, gift_cnt, room_id);
            }); else for (let j = 0; j < gift_cnt; j++) await sleep(100).then(() => {
                sendGift_bag(gift_id, 1, room_id);
            });
        }
        showMessage("【清空背包】执行完毕！", "success");
    } else showMessage("背包礼物为空", "error");
}

