function initPkg_ExIcon() {
    initPkg_ExIcon_insertDom(), initPkg_ExIcon_Func();
}

function initPkg_ExIcon_insertDom() {
    let a = document.createElement("div");
    a.className = "ex-icon", a.innerHTML = `<a title="DouyuEx ver.${curVersion}" role="button" tabindex="0" aria-label="DouyuEx 菜单（回车展开 / 收起）">${PokeballIcon_svg}<i id="ex-icon__tip" class="ex-panel__tip"></i></a>`;
    let b = document.querySelector(".PlayerToolbar-ContentCell .PlayerToolbar-Wealth") || document.querySelector(".ToolbarGiftArea-container") || document.querySelector(".PlayerToolbar") || document.querySelector(".BackpackButton")?.parentNode || document.body;
    if (b) b.appendChild(a);
}

function initPkg_ExIcon_Func() {
    let icon = document.getElementsByClassName("ex-icon")[0];
    if (icon) icon.addEventListener("keydown", e => {
        if ("Enter" === e.key || " " === e.key || 13 === e.keyCode || 32 === e.keyCode) e.preventDefault(), 
        icon.click();
    }), icon.addEventListener("click", e => {
        if (e.stopPropagation(), "function" === typeof isAnyThirdLevelPanelOpen && isAnyThirdLevelPanelOpen()) {
            if ("function" === typeof ExPanel_closeAllMenus) ExPanel_closeAllMenus(); else {
                if ("function" === typeof ExPanel_closeAllThirdLevel) ExPanel_closeAllThirdLevel();
                if ("function" === typeof hideExPanel) hideExPanel();
            }
            return;
        }
        if ("function" === typeof toggleExPanel) toggleExPanel(); else if ("function" === typeof showExPanel) showExPanel();
    });
}

function ExIcon_showTip(a) {
    let d = document.getElementById("ex-icon__tip");
    if (!d) return;
    if (true == a) d.style.display = "block"; else d.style.display = "none";
}

