function fetchCurrentRoomGifts(room_id, callback) {
    var numRid = String(room_id || rid || "");
    var exclusiveGifts = [];
    var universalGifts = [];
    var doneCount = 0;
    function finish() {
        if (++doneCount < 2) return;
        var combinedMap = {};
        universalGifts.forEach(g => {
            combinedMap[g.id] = g;
        }), exclusiveGifts.forEach(g => {
            combinedMap[g.id] = g;
        });
        var merged = [];
        for (var id in combinedMap) if (combinedMap.hasOwnProperty(id)) merged.push(combinedMap[id]), 
        _lastRoomGiftsMapByName[combinedMap[id].name] = combinedMap[id];
        if (merged.sort((a, b) => b.price - a.price), "function" === typeof callback) callback(merged);
    }
    try {
        var winData = "undefined" !== typeof unsafeWindow && unsafeWindow.$DATA ? unsafeWindow.$DATA : "undefined" !== typeof window && window.$DATA ? window.$DATA : null;
        if (winData && winData.room_gift && winData.room_gift.gift) exclusiveGifts = parseRoomGiftMap(winData.room_gift.gift), 
        finish(); else fetchBetardExclusive();
    } catch (e) {
        fetchBetardExclusive();
    }
    function fetchBetardExclusive() {
        var betardUrl = "https://www.douyu.com/betard/" + numRid;
        var handleBetard = json => {
            if (json && json.room_gift && json.room_gift.gift) exclusiveGifts = parseRoomGiftMap(json.room_gift.gift);
            finish();
        };
        if ("function" === typeof GM_xmlhttpRequest) GM_xmlhttpRequest({
            method: "GET",
            url: betardUrl,
            responseType: "json",
            headers: {
                Referer: "https://www.douyu.com/" + numRid
            },
            onload: res => {
                handleBetard(res.response || {});
            },
            onerror: () => {
                finish();
            }
        }); else fetch(betardUrl, {
            credentials: "include"
        }).then(r => r.json()).then(handleBetard).catch(() => {
            finish();
        });
    }
    room_id = "https://open.douyucdn.cn/api/RoomApi/room/" + numRid;
    var handleRoomApi = json => {
        if (json && json.data && Array.isArray(json.data.gift)) universalGifts = parseRoomApiUniversalGifts(json.data.gift);
        finish();
    };
    if ("function" === typeof GM_xmlhttpRequest) GM_xmlhttpRequest({
        method: "GET",
        url: room_id,
        responseType: "json",
        onload: res => {
            handleRoomApi(res.response || {});
        },
        onerror: () => {
            finish();
        }
    }); else fetch(room_id).then(r => r.json()).then(handleRoomApi).catch(() => {
        finish();
    });
}

