class GracefulP2PBlocker {
    constructor() {
        this.connectionState = "failed", this.iceConnectionState = "failed", this.signalingState = "closed", 
        this.iceGatheringState = "complete", this.localDescription = null, this.remoteDescription = null, 
        this.onicecandidate = null, this.ontrack = null, this.ondatachannel = null;
    }
    createDataChannel() {
        return {
            send: function() {},
            close: function() {},
            addEventListener: function() {},
            removeEventListener: function() {},
            readyState: "closed"
        };
    }
    createOffer() {
        return GracefulP2PBlocker_fail("WebRTC P2P disabled by user policy");
    }
    createAnswer() {
        return GracefulP2PBlocker_fail("WebRTC P2P disabled by user policy");
    }
    setLocalDescription() {
        return Promise.resolve();
    }
    setRemoteDescription() {
        return Promise.resolve();
    }
    addIceCandidate() {
        return Promise.resolve();
    }
    addEventListener() {}
    removeEventListener() {}
    dispatchEvent() {
        return false;
    }
    close() {}
    getStats() {
        return Promise.resolve(new Map());
    }
}

function killP2P() {
    let funNameList = [ "RTCPeerConnection", "webkitRTCPeerConnection", "mozRTCPeerConnection", "msRTCPeerConnection" ];
    funNameList.forEach(name => {
        if ("undefined" === typeof unsafeWindow.RTCPeerConnection) unsafeWindow.RTCPeerConnection = unsafeWindow[name];
        try {
            unsafeWindow[name] = GracefulP2PBlocker;
        } catch (err) {}
        try {
            window[name] = GracefulP2PBlocker;
        } catch (err) {}
    });
}

let redpackets_room_arr = [];

let redpacket_room_timer;

const REDPACKET_ROOM_MAX_FAIL = 3;

const REDPACKET_ROOM_MAX_GRAB = 5;

let redpacketRoomFailCount = 0;

function initPkg_ExpandTool_RedPacket_Room() {
    ExpandTool_RedPacket_Room_insertFunc(), ExpandTool_RedPacket_Room_Set();
}

function ExpandTool_RedPacket_Room_stop(message) {
    const box = document.getElementById("extool__redpacekt_room_start");
    if (box) box.checked = false;
    if (redpacket_room_timer) clearInterval(redpacket_room_timer);
    if (redpacket_room_timer = 0, redpacketRoomFailCount = 0, saveData_RedPacket_Room(), 
    message) showMessage(message, "error");
}

function ExpandTool_RedPacket_Room_insertFunc() {
    const box = document.getElementById("extool__redpacekt_room_start");
    if (!box) {
        if ("function" === typeof ExGuard_warn) ExGuard_warn("礼物红包", "面板里的开关不存在，本次不绑定（其它扩展功能不受影响）");
        return;
    }
    box.addEventListener("click", function() {
        verifyFans("5189167", 6).then(r => {
            if (true == r) {
                if (true == box.checked) {
                    if (redpacketRoomFailCount = 0, redpacket_room_timer) clearInterval(redpacket_room_timer);
                    redpacket_room_timer = setInterval(() => {
                        getRoomRedPacketsList(rid);
                    }, 6e4);
                } else {
                    if (redpacket_room_timer) clearInterval(redpacket_room_timer);
                    redpacket_room_timer = 0, redpacketRoomFailCount = 0;
                }
                saveData_RedPacket_Room();
            } else box.checked = false, saveData_RedPacket_Room(), showMessage("本功能需拥有6级歆崽粉丝牌(5189167)才可使用", "error");
        }).catch(err => {
            if ("function" === typeof ExGuard_warn) ExGuard_warn("礼物红包", "粉丝牌校验失败，已复位开关", err);
            ExpandTool_RedPacket_Room_stop("【礼物红包】网络异常，请重试");
        });
    });
}

function getRoomRedPacketsList(room_id) {
    return fetch("https://www.douyu.com/japi/interactnc/web/propredpacket/getPrpList?type_id=1&room_id=" + room_id, {
        method: "GET",
        mode: "no-cors",
        credentials: "include",
        headers: {
            "Content-Type": "application/x-www-form-urlencoded"
        }
    }).then(res => res.json()).then(ret => {
        const list = ret && ret.data && Array.isArray(ret.data.list) ? ret.data.list : null;
        if (!list) throw new Error("红包列表结构不符合预期（缺少 data.list）");
        if (redpacketRoomFailCount = 0, 0 === list.length) return;
        for (let i = 0; i < list.length; i++) {
            let rpid = list[i].activityid;
            let offset = redpackets_room_arr.indexOf(rpid);
            let startTime = list[i].startTime;
            let to = Number(startTime) - Math.round(new Date().getTime() / 1e3);
            if (to = 1e3 * to - 2e3, -1 == offset) if (redpackets_room_arr.push(rpid), 
            to > 0) setTimeout(() => {
                getRoomRedPacket(rpid), getRoomRedPacket(rpid), getRoomRedPacket(rpid), 
                showMessage("【礼物红包】抢红包执行完毕！", "success");
            }, to); else getRoomRedPacket(rpid), getRoomRedPacket(rpid), getRoomRedPacket(rpid), 
            showMessage("【礼物红包】抢红包执行完毕！", "success");
        }
    }).catch(err => {
        if (redpacketRoomFailCount++, "function" === typeof ExGuard_warn) ExGuard_warn("礼物红包", "第 " + redpacketRoomFailCount + " 次拉取红包列表失败（每 60 秒重试一次）", err);
        if (redpacketRoomFailCount >= REDPACKET_ROOM_MAX_FAIL) ExpandTool_RedPacket_Room_stop("【礼物红包】连续 " + REDPACKET_ROOM_MAX_FAIL + " 次拉取失败，已自动关闭");
    });
}

function getRoomRedPacket(rpid, attempt) {
    const tried = Number(attempt) || 0;
    return fetch("https://www.douyu.com/japi/interactnc/web/propredpacket/grab_prp", {
        method: "POST",
        mode: "no-cors",
        credentials: "include",
        headers: {
            "Content-Type": "application/x-www-form-urlencoded"
        },
        body: "activityid=" + rpid + "&ctn=" + getCCN()
    }).then(res => res.json()).then(ret => {
        const isSuc = ret && ret.data ? ret.data.isSuc : null;
        if (2 != isSuc) return;
        if (tried + 1 >= REDPACKET_ROOM_MAX_GRAB) {
            if ("function" === typeof ExGuard_warn) ExGuard_warn("礼物红包", "红包 " + rpid + " 补抢 " + REDPACKET_ROOM_MAX_GRAB + " 次仍未成功，放弃");
            return;
        }
        getRoomRedPacket(rpid, tried + 1);
    }).catch(err => {
        if ("function" === typeof ExGuard_warn) ExGuard_warn("礼物红包", "抢红包请求失败（" + rpid + "）", err);
    });
}

