    html += '<input class="dx-ml-10" type="button" id="extool__sendgift_btn" value="送出" />';
    let a = document.createElement("div");
    a.className = "extool__sendgift", a.innerHTML = html;
    let b = document.getElementsByClassName("extool")[0];
    if (!b) {
        if ("function" === typeof ExGuard_warn) ExGuard_warn("送礼", "未找到 .extool 容器，打榜送礼面板本次不插入");
        return false;
    }
    return b.insertBefore(a, b.childNodes[0]), true;
