if ("undefined" !== typeof window) window.ExUI = ExUI;

var FansBadgeList_hook = null;

function initPkg_FansBadgeList() {
    if (FansBadgeList_annotateRows()) return;
    if ("function" === typeof DomHook) {
        let lastRun = 0;
        try {
            if (FansBadgeList_hook = new DomHook("body", true, function() {
                const now = Date.now();
                if (now - lastRun < 400) return;
                lastRun = now, FansBadgeList_annotateRows();
            }), !FansBadgeList_hook.failed) return;
        } catch (e) {
            if ("function" === typeof ExGuard_warn) ExGuard_warn("粉丝牌页", "浮层监听挂不上，退回有上限轮询", e);
        }
    }
    if ("function" !== typeof ExGuard_pollFor) return;
    ExGuard_pollFor(function() {
        const rows = document.querySelectorAll(".fans-badge-list tr");
        return rows.length > 1 ? document.querySelector(".fans-badge-list") : null;
    }, function() {
        FansBadgeList_annotateRows();
    }, {
        intervalMs: 500,
        maxTries: 20,
        tag: "粉丝牌页",
        quiet: true
    });
}

function FansBadgeList_annotateRows() {
    let nowTime = new Date().getTime();
    let items = document.querySelectorAll(".fans-badge-list tr");
    if (items.length <= 1) return false;
    let annotated = 0;
    let skipped = 0;
    for (let i = 1; i < items.length; i++) {
        let item = items[i];
        if (item.dataset && "1" === item.dataset.exFansAnnotated) continue;
        try {
            let td = item.getElementsByTagName("td")[1];
            if (!td) {
                skipped++;
                continue;
            }
            let raw = item.getAttribute("data-fans-gbdgts");
            let tt = 1e3 * Number(raw);
            if (!raw || !isFinite(tt) || tt <= 0) {
                skipped++;
                continue;
            }
            let ttStr = dateFormat("yyyy-MM-dd hh:mm:ss", new Date(tt));
            let days = Math.floor((nowTime - tt) / 864e5);
            let longTerm = days >= 300;
            if (td.innerHTML += `
        已获取 <span class="${longTerm ? "is-long-term" : ""}">${days}</span> 天<br/>
        ` + ttStr, item.dataset) item.dataset.exFansAnnotated = "1";
            annotated++;
        } catch (e) {
            skipped++;
        }
    }
    if (skipped > 0 && "function" === typeof ExGuard_warn) ExGuard_warn("粉丝牌页", "有 " + skipped + " 行结构不符合预期（缺列或缺获取时间），已跳过；成功注释 " + annotated + " 行");
    return true;
}

let FansContinue_refreshBound = false;

