function LiveTool_reportHandlerError(name, err) {
    let e = err || {};
    console.error("[DouyuEx] 弹幕处理器异常：" + name + " —— " + (e.message || e));
}

function LiveTool_dispatchBarrage(ret) {
    let handlers = LiveTool_barrageHandlers();
    let failed = [];
    for (let i = 0; i < handlers.length; i++) {
        let name = handlers[i][0];
        let fn = handlers[i][1];
        if ("function" !== typeof fn) continue;
        try {
            let out = fn(ret);
            if (out && "function" === typeof out.then) out.catch(function(err) {
                LiveTool_reportHandlerError(name + "（async）", err);
            });
        } catch (err) {
            failed.push(name), LiveTool_reportHandlerError(name, err);
        }
    }
    return failed;
}

function LiveTool_parseKeywordRule(key) {
    let text = String(null == key ? "" : key);
    let open = text.indexOf("re(");
    if (-1 === open) return {
        kind: "literal",
        word: text
    };
    let close = text.indexOf(")=", open + 3);
    if (-1 === close) return {
        kind: "invalid",
        source: text,
        reason: "缺少 )=期望匹配"
    };
    return {
        kind: "regex",
        source: text.slice(open + 3, close),
        expect: text.slice(close + 2)
    };
}

function LiveTool_keywordRuleHit(key, txt) {
    let rule = LiveTool_parseKeywordRule(key);
    if ("literal" === rule.kind) {
        if ("" === rule.word) return false;
        return -1 !== String(txt).indexOf(rule.word);
    }
    if ("regex" === rule.kind) {
        let regObj;
        try {
            regObj = new RegExp(rule.source, "g");
        } catch (e) {
            return console.warn("[DouyuEx] 无效的正则关键词规则（已跳过）：" + key + " —— " + (e && e.message || e)), 
            false;
        }
        let result = regObj.exec(String(txt));
        return !!(result && result[0] === rule.expect);
    }
    return false;
}

function getType(str) {
    return getStrMiddle(str, "type@=", "/");
}

function selectOptionByValue(selectId, checkValue) {
    let select = document.getElementById(selectId);
    for (let i = 0; i < select.options.length; i++) if (select.options[i].value == checkValue) {
        select.options[i].selected = true;
        break;
    }
}

function LiveTool_cellHead(cell) {
    cell = cell.querySelector(".ui-cell__title");
    var txt = cell ? String(cell.textContent).replace(/\s+/g, "") : "";
    var keys = [ "关键词回复", "关键词禁言", "进场欢迎", "自动谢礼物", "弹幕投票" ];
    for (var i = 0; i < keys.length; i++) if (0 === txt.indexOf(keys[i])) return keys[i];
    return txt.slice(0, 8);
}

function LiveTool_sortCells() {
    var body = document.querySelector(".livetool .miuix-modal__body");
    if (!body) return;
    var rank = {
        "关键词回复": 1,
        "关键词禁言": 2,
        "进场欢迎": 3,
        "自动谢礼物": 4,
        "弹幕投票": 5
    };
    var cells = Array.prototype.slice.call(body.querySelectorAll(":scope > .ui-cell"));
    if (cells.length < 2) return;
    cells.forEach(function(c, i) {
        c.dataset.exIdx = String(i);
    });
    var before = cells.slice();
    cells.sort(function(a, b) {
        var ta = LiveTool_cellHead(a);
        var tb = LiveTool_cellHead(b);
        if (ta = rank[ta.trim()] || 99, tb = rank[tb.trim()] || 99, ta !== tb) return ta - tb;
        return Number(a.dataset.exIdx) - Number(b.dataset.exIdx);
    });
    var same = true;
    for (var i = 0; i < cells.length; i++) if (cells[i] !== before[i]) {
        same = false;
        break;
    }
    if (same) return;
    cells.forEach(function(c) {
        body.appendChild(c);
    });
}

