function initPkg_Lottery_Func() {
    let dom_notice = document.getElementById("lottery-notice");
    const iconDom = document.getElementsByClassName("ex-lottery")[0];
    if (!iconDom) ExGuard_warn("抽奖", "入口图标不存在，抽奖面板无法打开"); else iconDom.addEventListener("click", function() {
        try {
            showExRightPanel("全站抽奖信息", this);
            let dom = document.getElementsByClassName("lottery__wrap")[0];
            if (dom) dom.innerHTML = lotteryHTML;
            if (!lotteryHTML) initPkg_Lottery_Timer();
        } catch (e) {
            ExGuard_warn("抽奖", "打开抽奖面板失败", e);
        }
    });
    const refreshDom = document.getElementById("lottery-refresh");
    if (!refreshDom) ExGuard_warn("抽奖", "刷新按钮不存在，面板刷新不可用"); else {
        const refreshHandler = function() {
            initPkg_Lottery_Timer();
        };
        refreshDom.addEventListener("click", "function" === typeof debounce ? debounce(refreshHandler, 3e3) : refreshHandler);
    }
    function startLotteryTimer() {
        stopLotteryTimer(), initPkg_Lottery_Timer(), timer_lottery = setInterval(() => {
            if (isLotteryNotice) initPkg_Lottery_Timer(); else stopLotteryTimer();
        }, 6e4);
    }
    function stopLotteryTimer() {
        if (timer_lottery) clearInterval(timer_lottery), timer_lottery = 0;
    }
    if (!dom_notice) return ExGuard_warn("抽奖", "提醒开关不存在，抽奖提醒本次不可用"), void 0;
    dom_notice.addEventListener("click", () => {
        let ischecked = dom_notice.checked;
        if (true == ischecked) isLotteryNotice = true, startLotteryTimer(); else isLotteryNotice = false, 
        stopLotteryTimer();
        saveData_Lottery();
    });
}

async function initPkg_Lottery_Timer() {
    if (Object.keys(lotteryHasNoticed).length > 100) lotteryHasNoticed = {};
    let html = "";
    const hall = await ExGuard_withTimeout(getExLotteryList(), 15e3, "抽奖");
    const list = hall && hall.data ? hall.data.list : null;
    if (!Array.isArray(list)) return ExGuard_warn("抽奖", "抽奖大厅接口没有返回 list，本次不更新列表"), 
    lotteryHTML = "", lotteryRenderNodata(), void 0;
    const maxRooms = list.length > LOTTERY_MAX_ROOMS ? LOTTERY_MAX_ROOMS : list.length;
    if (maxRooms < list.length) ExGuard_warn("抽奖", "在播抽奖过多（" + list.length + " 个），本次只取前 " + LOTTERY_MAX_ROOMS + " 个");
    for (let i = 0; i < maxRooms; i++) {
        const item = list[i];
        try {
            if (0 !== item.status) continue;
            const lotteryInfo = await ExGuard_withTimeout(getExLotteryInfo(item.room_id), 12e3, "抽奖");
            const data = lotteryInfo && lotteryInfo.data ? lotteryInfo.data : null;
            if (!data || !data.join_condition) {
                ExGuard_warn("抽奖", "房间 " + item.room_id + " 的抽奖详情不完整，跳过");
                continue;
            }
            let condition = data.join_condition;
            let joinText = "command_content" in condition ? `发送弹幕` : `赠送 ${condition.gift_name}（${condition.gift_price}）x` + condition.gift_num;
            let expireTime = Number(data.start_at) + Number(data.join_condition.expire_time);
            let expireText = getTimeDiff(1e3 * expireTime, new Date().getTime());
            expireText = -1 == expireText ? "已结束" : "距结束：" + expireText;
            let canJoin = -1 !== myFansBadgeList.indexOf(String(item.room_id)) || condition.lottery_range <= 1;
            if (canJoin && isLotteryNotice) {
                let keyName = data.prize_name + `|` + data.start_at;
                if (!(keyName in lotteryHasNoticed)) lotteryHasNoticed[keyName] = 1, 
                showMessage(`<a class="dx-fs-14 dx-bd-none" target="_blank" href="https://www.douyu.com/${item.room_id}" >【${data.prize_name}x${data.prize_num}】${joinText}</a>`, "special", {
                    timeout: 100
                });
            }
            html += `
            <a class="lottery__a" href="https://www.douyu.com/${item.room_id}" target="_blank">
                <div class="lottery__item">
                    <div class="lottery__img">
                        <div class="lottery__anchor">${item.anchor_name}</div>
                        <img loading="lazy" src="${item.verticalSrc}"/>
                        <div class="lottery__expireTime">${expireText}</div>
                    </div>
                    <div class="lottery__info">
                        <div class="lottery__prize">${data.prize_name}x${data.prize_num}</div>
                        <div class="lottery__jointext">${joinText}</div>
                        <div class="lottery__condition${canJoin ? "" : " is-blocked"}">${getJoinCondition(condition)}</div>
                    </div>
                </div>
            </a>
        `;
        } catch (e) {
            ExGuard_warn("抽奖", "房间 " + item.room_id + " 的抽奖信息获取失败，跳过", e);
        }
    }
    lotteryHTML = html, lotteryRenderNodata();
    const dom = document.getElementsByClassName("lottery__wrap")[0];
    if (dom) dom.innerHTML = lotteryHTML;
}

function lotteryRenderNodata() {
    const domNodata = document.getElementsByClassName("lottery__nodata")[0];
    if (!domNodata) return;
    domNodata.style.display = "" !== lotteryHTML.trim() ? "none" : "block";
}

function getJoinCondition(condition) {
    let ret = "";
    switch (condition.lottery_range) {
      case 0:
        ret = "所有人可参与";
        break;

      case 1:
        ret = "关注主播";
        break;

      case 2:
        ret = "成为粉丝";
        break;

      case 3:
        ret = "关注主播+成为粉丝";
        break;

      default:
        break;
    }
    return ret;
}

function getExLotteryList() {
    return ExGuard_xhr({
        method: "GET",
        url: "https://www.douyu.com/lapi/interact/lottery/getHallList",
        responseType: "json",
        tag: "抽奖"
    }, 15e3);
}

function getExLotteryInfo(room_id) {
    return new Promise((resolve, reject) => {
        fetch("https://www.douyu.com/member/lottery/activity_info?room_id=" + room_id, {
            method: "GET",
            mode: "no-cors",
            credentials: "include",
            headers: {
                "Content-Type": "application/x-www-form-urlencoded"
            }
        }).then(res => res.json()).then(ret => {
            resolve(ret);
        }).catch(err => {
            reject(err);
        });
    });
}

async function setFansBadgeList() {
    let ret = [];
    try {
        const doc = await fetch("https://www.douyu.com/member/cp/getFansBadgeList", {
            method: "GET",
            mode: "no-cors",
            cache: "default",
            credentials: "include"
        }).then(res => res.text()).then(text => new DOMParser().parseFromString(String(text || ""), "text/html"));
        const list = doc ? doc.getElementsByClassName("fans-badge-list")[0] : null;
        if (!list || !list.lastElementChild) return ExGuard_warn("抽奖", "粉丝牌列表结构不符合预期（未登录或页面改版），按「没有粉丝牌」处理"), 
        myFansBadgeList = [], void 0;
        const last = list.lastElementChild;
        for (let i = 0; i < last.children.length; i++) {
            const roomId = last.children[i].getAttribute("data-fans-room");
            if (roomId) ret.push(roomId);
        }
        myFansBadgeList = ret;
    } catch (e) {
        ExGuard_warn("抽奖", "粉丝牌列表请求失败，按「没有粉丝牌」处理", e), myFansBadgeList = [];
    }
}

function saveData_Lottery() {
    let data = {
        isNotice: isLotteryNotice
    };
    localStorage.setItem("ExSave_Lottery", JSON.stringify(data));
}

function Lottery_Set() {
    const saved = localStorage.getItem("ExSave_Lottery");
    if (null == saved) return;
    let parsed = null;
    try {
        parsed = JSON.parse(saved);
    } catch (e) {
        return ExGuard_warn("抽奖", "本地存储的抽奖设置已损坏，按未开启处理", e), void 0;
    }
    if (parsed && true == parsed.isNotice) {
        const checkbox = document.getElementById("lottery-notice");
        if (checkbox) checkbox.click(); else ExGuard_warn("抽奖", "提醒开关不存在，无法恢复上次的开启状态");
    }
}

function initPkg_Menu() {
    if ("function" !== typeof GM_registerMenuCommand) {
        if ("function" === typeof ExGuard_warn) ExGuard_warn("菜单", "当前脚本管理器不支持 GM_registerMenuCommand，右键菜单项不可用（其它功能不受影响）");
        return;
    }
    GM_registerMenuCommand("检查更新", function() {
        try {
            if ("function" === typeof showExRightPanel) return showExRightPanel("版本更新", null, true), 
            void 0;
            if ("function" === typeof createExUpdatePanel) return createExUpdatePanel(), 
            void 0;
        } catch (e) {
            if ("function" === typeof ExGuard_warn) ExGuard_warn("菜单", "打开版本更新面板失败", e);
        }
        if ("function" === typeof showMessage) showMessage("【版本更新】面板暂不可用，请刷新页面后从胶囊条进入", "error");
    });
}

