const ROOM_REVENUE_INTERVAL = 15e4;

const ROOM_REVENUE_API = "https://dy.roozj.com/api/ranking/anchors";

let roomRevenueState = {
    initialized: false,
    enabled: true,
    timer: null,
    waitTimer: null,
    waitTries: 0,
    request: null,
    context: null,
    blockedRid: "",
    cache: new Map(),
    income: null,
    donors: null,
    paidDonors: null,
    speakers: null,
    updatedAt: null,
    loading: false,
    stale: false,
    message: ""
};

let roomRevenueRankNode = null;

function RoomRevenue_id(value) {
    const text = void 0 === value || null === value ? "" : String(value).trim();
    return /^[1-9]\d*$/.test(text) ? text : "";
}

function RoomRevenue_today() {
    const now = new Date();
    return now.getFullYear() + "-" + String(now.getMonth() + 1).padStart(2, "0") + "-" + String(now.getDate()).padStart(2, "0");
}

function RoomRevenue_abort() {
    const request = roomRevenueState.request;
    if (roomRevenueState.request = null, roomRevenueState.loading = false, request) {
        request.done = true;
        try {
            if (request.handle && request.handle.abort) request.handle.abort();
        } catch (error) {}
    }
}

function RoomRevenue_syncContext() {
    const state = roomRevenueState;
    const path = window.location.pathname;
    const shortId = RoomRevenue_id((path.match(/^\/(?:beta\/)?(\d+)(?:\/|$)/) || [])[1]);
    let realId = RoomRevenue_id("undefined" === typeof rid ? "" : rid);
    if (state.context && state.context.path !== path) state.blockedRid = state.context.realId || state.blockedRid;
    if (state.blockedRid && realId === state.blockedRid && shortId !== realId) realId = ""; else if (realId !== state.blockedRid || realId === shortId) state.blockedRid = "";
    const date = RoomRevenue_today();
    const context = {
        path: path,
        realId: realId,
        shortId: shortId,
        date: date
    };
    if (context.key = [ path, realId, shortId, date ].join("|"), !state.context || state.context.key !== context.key) {
        RoomRevenue_abort(), state.context = context;
        const cached = state.cache.get(context.key);
        state.income = cached ? cached.income : null, state.donors = cached ? cached.donors : null, 
        state.paidDonors = cached ? cached.paidDonors : null, state.speakers = cached ? cached.speakers : null, 
        state.updatedAt = cached ? cached.updatedAt : null, state.stale = !!(cached && Date.now() - cached.updatedAt >= ROOM_REVENUE_INTERVAL), 
        state.message = "";
    }
    return state.context;
}

function RoomRevenue_visible() {
    try {
        let prototype = Object.getPrototypeOf(document);
        while (prototype) {
            const hidden = Object.getOwnPropertyDescriptor(prototype, "hidden");
            if (hidden && hidden.get) return !hidden.get.call(document);
            prototype = Object.getPrototypeOf(prototype);
        }
    } catch (error) {}
    return !document.hidden && "hidden" !== document.visibilityState;
}

function RoomRevenue_render() {
    const node = document.querySelector(".ex-room-revenue");
    if (!node) return;
    const state = roomRevenueState;
    const value = node.querySelector(".ex-room-revenue__value");
    let text = "";
    if (null !== state.income) {
        if (text += (state.income > 0 && state.income < .01 ? "<0.01" : state.income.toLocaleString("zh-CN", {
            maximumFractionDigits: 2
        })) + "鱼翅", state.stale) text += "（上次）";
    } else text = state.loading ? "…" : "—";
    if (value) value.textContent = text;
    const refresh = node.querySelector(".ex-room-revenue__refresh");
    if (refresh) refresh.disabled = state.loading;
    const date = state.context ? state.context.date : RoomRevenue_today();
    const detail = [ "统计日期：" + date + "（本地今日）", "来源：dy.roozj.com 公开榜单；单位：鱼翅", "第三方统计流水，不代表主播实际到账收入" ];
    if (null !== state.income) detail.push("公开流水数值：" + state.income + "鱼翅");
    if (null !== state.donors) detail.push("送礼人数：" + state.donors);
    if (null !== state.paidDonors) detail.push("付费送礼人数：" + state.paidDonors);
    if (null !== state.speakers && void 0 !== state.speakers) detail.push("今日发言人数：" + state.speakers);
    if (null !== state.updatedAt) detail.push("获取时间：" + new Date(state.updatedAt).toLocaleString());
    if (state.stale) detail.push("显示上次成功结果");
    if (state.loading) detail.push("正在刷新");
    if (state.message) detail.push(state.message);
    node.title = detail.join("\n");
    const metrics = [ [ "donors", state.donors, "今日送礼人数", "total_fans" ], [ "speakers", state.speakers, "今日发言人数", "danmu_users" ] ];
    for (var [ name, count, label, field ] of metrics) {
        const item = node.querySelector('[data-revenue-metric="' + name + '"]');
        const number = node.querySelector(".ex-room-revenue__" + name);
        const formatted = null === count || void 0 === count ? "—" : count.toLocaleString("zh-CN");
        if (number) number.textContent = formatted;
        if (item) item.title = label + "（公开榜单 " + field + "）：" + formatted + "\n" + node.title, 
        item.setAttribute("aria-label", label + " " + formatted);
    }
    const money = node.querySelector('[data-revenue-metric="income"]');
    if (money) money.title = "今日流水（公开榜单 total_income，单位：鱼翅）\n" + node.title, money.setAttribute("aria-label", "今日流水 " + text);
}

