function setScrollFunc(scrollDom, barDom, maskDom, callback) {
    if (!scrollDom || !barDom || !maskDom) return;
    let scroll = scrollDom;
    let bar = barDom;
    let mask = maskDom;
    let barleft = 0;
    bar.onmousedown = function(e) {
        let event = e || window.event;
        let leftVal = event.clientX - this.offsetLeft;
        let that = this;
        function onMouseMove(e) {
            let event = e || window.event;
            if (barleft = event.clientX - leftVal, barleft < 0) barleft = 0; else if (barleft > scroll.offsetWidth - bar.offsetWidth) barleft = scroll.offsetWidth - bar.offsetWidth;
            mask.style.width = barleft + "px", that.style.left = barleft + "px", 
            callback(parseInt(barleft / (scroll.offsetWidth - bar.offsetWidth) * 255)), 
            window.getSelection ? window.getSelection().removeAllRanges() : document.selection.empty();
        }
        function onMouseUp() {
            document.removeEventListener("mousemove", onMouseMove), document.removeEventListener("mouseup", onMouseUp);
        }
        document.addEventListener("mousemove", onMouseMove), document.addEventListener("mouseup", onMouseUp);
    };
}

