    if (isTrigger) el.addEventListener("mouseenter", VideoToolbarMenu_onTriggerEnter), 
    el.addEventListener("pointerenter", VideoToolbarMenu_onTriggerEnter); else el.addEventListener("mouseenter", VideoToolbarMenu_onMenuZoneEnter), 
    el.addEventListener("pointerenter", VideoToolbarMenu_onMenuZoneEnter);
